const LON0 = 68.16239;
const LAT1 = 37.09759;
const K = 0.920505;
const SCALE = 37.16216;

/** Longitude/latitude to a point in INDIA_VIEWBOX. */
export function indiaPoint(lon: number, lat: number): { x: number; y: number } {
  return { x: (lon - LON0) * K * SCALE, y: (LAT1 - lat) * SCALE };
}
